/*
 * Loader of one Axon model slot, compiled once per slot by model_ota_add_slot_library().
 * Defines model_ota_load_axon_<target>().
 */

#include <model_ota/model_ota_axon.h>

#include "model_contract.h"
#include "model_image_axon.h"
#include "model_ota_slot.h"

/* Slot capacities, generated by axon_elf.py inspect. */
#include "model_ota_axon_model_config.h"

#define MODEL_OTA_AXON_CONTRACT_HASH MODEL_OTA_CONTRACT_HASH_AXON(MODEL_OTA_PARTITION_ADDR)

MODEL_OTA_CONTRACT_HASH_EXPORT(MODEL_OTA_AXON_CONTRACT_HASH);

MODEL_OTA_AXON_LOAD_DECL(MODEL_OTA_SLOT_TARGET)
{
	static const struct model_image_axon_expect expect = {
		.contract_hash = MODEL_OTA_AXON_CONTRACT_HASH,
		.persistent_vars_cap = MODEL_OTA_AXON_PERSISTENT_VARS_CAP,
		.packed_output_cap = MODEL_OTA_AXON_PACKED_OUTPUT_BYTES,
		.input_vector_cap = MODEL_OTA_AXON_INPUT_VECTOR_CAP,
	};

	if (out_model == NULL) {
		return MODEL_IMAGE_ERR_INVALID_ARG;
	}

	*out_model = NULL;

	return model_image_load_axon(MODEL_OTA_IMAGE_ADDR, MODEL_OTA_IMAGE_MAX_SIZE, &expect,
				     out_model);
}
